-- generated by tools/gencatalog, do not edit by hand

CREATE TABLE countries (
    id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    alpha2 VARCHAR(2) NOT NULL,
    alpha3 VARCHAR(3) NOT NULL,
    numeric_code VARCHAR(3) NOT NULL,
    name VARCHAR(128) NOT NULL,
    currency_id BIGINT REFERENCES currencies(id),
    is_deleted BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE country_revisions (
    id              BIGINT       PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    country_id BIGINT       NOT NULL REFERENCES countries(id) ON DELETE CASCADE,
    revision_number INTEGER      NOT NULL CHECK (revision_number >= 1),
    change          JSONB        NOT NULL,
    changed_by      UUID         NOT NULL,
    changed_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT uq_country_revisions_revision
        UNIQUE (country_id, revision_number)
);

CREATE UNIQUE INDEX uq_countries_alpha2
    ON countries (alpha2);

CREATE UNIQUE INDEX uq_countries_alpha3
    ON countries (alpha3);

CREATE UNIQUE INDEX uq_countries_numeric_code
    ON countries (numeric_code);

CREATE INDEX idx_countries_currency_id
    ON countries (currency_id);

CREATE INDEX idx_countries_active
    ON countries (id)
    WHERE is_deleted = FALSE;

CREATE INDEX idx_country_revisions_country_id
    ON country_revisions (country_id);

CREATE INDEX idx_country_revisions_covering_agg
    ON country_revisions (country_id, revision_number DESC)
    INCLUDE (changed_at, changed_by, change);

CREATE INDEX idx_country_revisions_changed_at
    ON country_revisions (changed_at);

CREATE OR REPLACE VIEW v_expanded_country AS
SELECT
    t.id,
    t.alpha2,
    t.alpha3,
    t.numeric_code,
    t.name,
    t.currency_id,
    t.is_deleted,
    agg.revision,
    agg.last_changer,
    agg.created_at,
    agg.updated_at,
    agg.deleted_at
FROM countries t
LEFT JOIN (
    SELECT
        country_id,
        MAX(revision_number) AS revision,
        MAX(changed_at) AS updated_at,
        (ARRAY_AGG(changed_by ORDER BY revision_number DESC))[1] AS last_changer,
        MIN(changed_at) FILTER (WHERE revision_number = 1) AS created_at,
        MAX(changed_at) FILTER (
            WHERE change @> '[{"path": "/is_deleted", "value": true}]'::jsonb
        ) AS deleted_at
    FROM country_revisions
    GROUP BY country_id
) agg ON agg.country_id = t.id;

COMMENT ON TABLE countries IS
    'Countries according to ISO 3166-1 with a reference to the main currency. Stores the current state of each record.';

COMMENT ON TABLE country_revisions IS
    'Immutable audit log of changes applied to countries. Read-only from the application perspective.';

COMMENT ON VIEW v_expanded_country IS
    'Read-only view that enriches each country with its latest revision number, '
    'last changer UUID, and lifecycle timestamps derived from the revision log.';
